1	export type Card = {
2	  monster: string;
3	  rank?: number;
4	};
5	
6	const SPHINX = "sphinx";
7	
8	const isSphinx = (card: Card): boolean => card.monster === SPHINX;
9	
10	const countDistinctTypes = (cards: Card[]): number =>
11	  new Set(cards.map((card) => card.monster)).size;
12	
13	const BASE_SCORE = 1;
14	const MINIMUM_BONUS = 1;
15	const POINTS_PER_EXTRA_TYPE = 2;
16	const TYPES_INCLUDED_IN_MINIMUM_BONUS = 3;
17	
18	const varietyBonusFor = (otherTypeCount: number): number =>
19	  Math.max(
20	    MINIMUM_BONUS,
21	    POINTS_PER_EXTRA_TYPE * (otherTypeCount - TYPES_INCLUDED_IN_MINIMUM_BONUS),
22	  );
23	
24	const cardsSeenBy = (army: Card[], scorerIndex: number): Card[] =>
25	  army.filter((_, index) => index !== scorerIndex);
26	
27	const scoreSphinxSeeing = (visibleCards: Card[]): number =>
28	  BASE_SCORE + varietyBonusFor(countDistinctTypes(visibleCards));
29	
30	export const scoreArmy = (army: Card[]): number =>
31	  army.reduce(
32	    (total, card, index) =>
33	      isSphinx(card)
34	        ? total + scoreSphinxSeeing(cardsSeenBy(army, index))
35	        : total,
36	    0,
37	  );
